                      color: Theme.of(
                        context,
                      ).colorScheme.primary.withValues(alpha: 0.35),
                    ),
                    borderRadius: BorderRadius.circular(16),
                  ),
                  child: Row(
                    children: [
                      Icon(
                        Icons.person_add_outlined,
                        color: Theme.of(context).colorScheme.primary,
                        size: 24,
                      ),
                      const SizedBox(width: 12),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'No member selected',
                              style: TextStyle(
                                fontWeight: FontWeight.w700,
                                fontSize: 14,
                                color: Theme.of(context).colorScheme.primary,
                              ),
                            ),
                            const SizedBox(height: 2),
                            Text(
                              'Tap here to choose a family member.',
                              style: theme.textTheme.bodySmall,
                            ),
                          ],
                        ),
                      ),
                      Icon(
                        Icons.arrow_forward_ios,
                        size: 14,
                        color: Theme.of(context).colorScheme.primary,
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(height: 14),
            ],

            // Family Head Portal Section (Contains the Hero Banner + 4 Metric Cards + Needs Attention + Doctor + Members + Actions)
            if (isHead)
              dashboardAsync.when(
                loading: () => const Padding(
                  padding: EdgeInsets.symmetric(vertical: 8),
                  child: LinearProgressIndicator(),
                ),
                error: (_, _) => const SizedBox.shrink(),
                data: (dashboard) => HeadDashboardSection(
                  dashboard: dashboard,
                  onNavigate: (path) => context.push(path),
                  activeMember: activeMember,
                  onTapProfile: () => _showProfileBottomSheet(
                    context,
                    ref,
                    activeMember,
                    ref.read(authProvider).userId,
                  ),
                ),
              )
            else if (isDoctor) ...[
              // Doctors get their own workspace; patient actions would call family-only endpoints.
              _SectionLabel('Clinical workspace'),
              _ActionRow(
                icon: Icons.monitor_heart_outlined,
                title: 'Triage cases',
                onTap: () => context.go('/triage-cases'),
              ),
              _ActionRow(
                icon: Icons.people_outline_rounded,
                title: 'My families',
                onTap: () => context.go('/families'),
              ),
              _ActionRow(
                icon: Icons.calendar_month_outlined,
                title: 'Calendar',
                onTap: () => context.go('/calendar'),
              ),
              _ActionRow(
                icon: Icons.badge_outlined,
                title: 'Profile & availability',
                onTap: () => context.push('/doctor-profile'),
              ),
            ] else ...[
              // Primary Task CTA (Web-style gradient card)
              _PrimaryAction(
                title: 'Describe a symptom',
                caption:
                    'A verified doctor reviews every response before it reaches you.',
                enabled: true,
                onTap: () =>
                    _handleMemberAction(context, '/complaints/new', hasMember),
              ),
              const SizedBox(height: 16),

              dashboardAsync.when(
                loading: () => const Padding(
                  padding: EdgeInsets.symmetric(vertical: 8),
                  child: LinearProgressIndicator(),
                ),
                error: (_, _) => const SizedBox.shrink(),
                data: (dashboard) => Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    GlassCard(
                      padding: const EdgeInsets.all(14),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            dashboard.nextAppointment == null
                                ? 'No upcoming appointment'
                                : 'Next appointment: '
                                    '${dashboard.nextAppointment!.status.friendlyLabel}',
                            style: theme.textTheme.titleSmall,
                          ),
                          const SizedBox(height: 4),
                          Text(
                            'Open cases: ${dashboard.openCases} · '
                            'Approved guidance: ${dashboard.approvedGuidanceCount}',
                            style: theme.textTheme.bodySmall,
                          ),
                          const SizedBox(height: 4),
                          Text(
                            dashboard.familyDoctor == null
                                ? 'No family doctor assigned yet'
                                : 'Family doctor: Dr. ${dashboard.familyDoctor!.displayName}',
                            style: theme.textTheme.bodySmall,
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 10),
                    const IncomingInvitationsSection(),
                  ],
                ),
              ),
            ],

            if (!isHead && !isDoctor) ...[
              const SizedBox(height: 16),
              _SectionLabel('Appointments & Care'),
              _ActionRow(
                icon: Icons.event_outlined,
                title: 'Appointments',
                onTap: () => context.push('/appointments'),
              ),
              _ActionRow(
                icon: Icons.add_task_outlined,
                title: 'Book appointment',
                enabled: true,
                onTap: () =>
                    _handleMemberAction(context, '/appointments/book', hasMember),
              ),
              _ActionRow(
                icon: Icons.medical_services_outlined,
                title: 'My Doctor',
                onTap: () => context.push('/my-doctor'),
              ),
              _ActionRow(
                icon: Icons.group_add_outlined,
                title: 'Join a family by code',
                onTap: () => context.push('/join-family'),
              ),

              const SizedBox(height: 16),
              _SectionLabel('Records & Vitals'),
              _ActionRow(
                icon: Icons.folder_outlined,
                title: 'Health records',
                enabled: true,
                onTap: () => _handleMemberAction(context, '/records', hasMember),
              ),
              _ActionRow(
                icon: Icons.note_add_outlined,
                title: 'Add health record',
                enabled: true,
                onTap: () =>
                    _handleMemberAction(context, '/records/new', hasMember),
              ),
              _ActionRow(
                icon: Icons.monitor_heart_outlined,
                title: 'Record vital',
                enabled: true,
                onTap: () =>
                    _handleMemberAction(context, '/vitals/new', hasMember),
              ),

              const SizedBox(height: 16),
              _SectionLabel('Triage & Cases'),
              _ActionRow(
                icon: Icons.track_changes_outlined,
                title: 'Case status',
                enabled: true,
                onTap: () => _handleMemberAction(context, '/cases', hasMember),
              ),

              const SizedBox(height: 22),
              // Rule 10: Emergency referral is solid red, high contrast.
              _EmergencyAction(onTap: () => context.push('/emergency')),
            ],
          ],
        ),
      ),
    ),
  );
  }
}

class _SectionLabel extends StatelessWidget {
  const _SectionLabel(this.text);

  final String text;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    return Padding(
      padding: const EdgeInsets.only(left: 2, bottom: 8),
      child: Row(
        children: [
          Container(
            width: 3.5,
            height: 11,
            decoration: BoxDecoration(
              color: isDark ? AppColors.primaryDark : AppColors.primary,
              borderRadius: BorderRadius.circular(2),
            ),
          ),
          const SizedBox(width: 6),
          Text(
            text.toUpperCase(),
            style: TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.w700,
              letterSpacing: 1.1,
              color: isDark ? AppColors.mutedDark : AppColors.muted,
            ),
          ),
        ],
      ),
    );
  }
}

class _PrimaryAction extends StatelessWidget {
  const _PrimaryAction({
    required this.title,
    required this.caption,
    required this.onTap,
    this.enabled = true,
  });

  final String title;
  final String caption;
  final VoidCallback onTap;
  final bool enabled;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final start = isDark ? AppColors.primaryLumDark : AppColors.primaryLum;
    final end = isDark ? AppColors.primaryDark : AppColors.primary;
    final onFill = isDark ? const Color(0xFF06100E) : Colors.white;

    return Opacity(
      opacity: enabled ? 1 : 0.5,
      child: Semantics(
        button: true,
        enabled: enabled,
        label: '$title. $caption',
        child: DecoratedBox(
          decoration: BoxDecoration(
            gradient: LinearGradient(
              begin: Alignment.topLeft,
              end: Alignment.bottomRight,
              colors: [start, end],
            ),
            borderRadius: const BorderRadius.all(Radius.circular(18)),
            boxShadow: [
              BoxShadow(
                color: end.withValues(alpha: 0.35),
                blurRadius: 20,
                offset: const Offset(0, 8),
                spreadRadius: -4,
              ),
            ],
          ),
          child: Material(
            color: Colors.transparent,
            child: InkWell(
              onTap: enabled ? onTap : null,
              borderRadius: const BorderRadius.all(Radius.circular(18)),
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      children: [
                        Expanded(
                          child: Text(
                            title,
                            style: TextStyle(
                              fontSize: 18,
                              fontWeight: FontWeight.w700,
                              letterSpacing: -0.2,
                              color: onFill,
                            ),
                          ),
                        ),
                        Container(
                          width: 34,
                          height: 34,
                          decoration: BoxDecoration(
                            color: onFill,
                            shape: BoxShape.circle,
                          ),
                          child: Icon(
                            Icons.arrow_forward,
                            size: 18,
                            color: end,
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 6),
                    Text(
                      caption,
                      style: TextStyle(
                        fontSize: 12.5,
                        height: 1.4,
                        color: onFill.withValues(alpha: 0.88),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _ActionRow extends StatelessWidget {
  const _ActionRow({
    required this.icon,
    required this.title,
    required this.onTap,
    this.enabled = true,
  });

  final IconData icon;
  final String title;
  final VoidCallback onTap;
  final bool enabled;

  @override
  Widget build(BuildContext context) {
    final primary = Theme.of(context).colorScheme.primary;
    return Padding(
      padding: const EdgeInsets.only(bottom: 8),
      child: Opacity(
        opacity: enabled ? 1 : 0.5,
        child: GlassCard(
          onTap: enabled ? onTap : null,
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
          child: Row(
            children: [
              Container(
                width: 36,
                height: 36,
                decoration: BoxDecoration(
                  color: primary.withValues(alpha: 0.12),
                  borderRadius: const BorderRadius.all(Radius.circular(10)),
                ),
                child: Icon(icon, size: 18, color: primary),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: Text(
                  title,
                  style: Theme.of(context).textTheme.titleSmall,
                ),
              ),
              Icon(
                Icons.chevron_right,
                size: 18,
                color: context.glass.faint,
              ),
            ],
          ),
        ),
      ),
    );
  }
}

class _EmergencyAction extends StatelessWidget {
  const _EmergencyAction({required this.onTap});

  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final emergency = context.glass.emergency;
    return SolidSurface(
      color: emergency,
      padding: EdgeInsets.zero,
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: onTap,
          borderRadius: const BorderRadius.all(Radius.circular(16)),
          child: const Padding(
            padding: EdgeInsets.symmetric(horizontal: 16, vertical: 14),
            child: Row(
              children: [
                Icon(Icons.emergency_outlined, color: Colors.white, size: 22),
                SizedBox(width: 12),
                Expanded(
                  child: Text(
                    'Emergency referral',
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 15,
                      fontWeight: FontWeight.w700,
                    ),
                  ),
                ),
                Icon(Icons.chevron_right, color: Colors.white, size: 18),
              ],
            ),
          ),
        ),
      ),
    );
  }
}

class _ProfileDetailRow extends StatelessWidget {
  const _ProfileDetailRow({
    required this.icon,
    required this.label,
    required this.value,
  });

  final IconData icon;
  final String label;
  final String value;

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    return Row(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Icon(
          icon,
          size: 18,
          color: isDark ? AppColors.mutedDark : AppColors.muted,
        ),
        const SizedBox(width: 10),
        Text(
          label,
          style: TextStyle(
            fontSize: 13,
            color: isDark ? AppColors.mutedDark : AppColors.muted,
          ),
        ),
        const Spacer(),
        Flexible(
          child: Text(
            value,
            textAlign: TextAlign.right,
            style: TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w600,
              color: isDark ? AppColors.textDark : AppColors.text,
            ),
          ),
        ),
      ],
    );
  }
}
